/* Stand-in for a self-hosted Adobe Launch library (demo only). */
window._satellite = window._satellite || { buildInfo: { environment: "production" }, track: function () {} };
window.s_c_il = window.s_c_il || [];
window.lemon = {
  // sends an Adobe Analytics style beacon to this site's own /b/ss/ path
  beacon: function (params) {
    var qs = Object.keys(params).map(function (k) { return k + "=" + encodeURIComponent(params[k]); }).join("&");
    new Image().src = "b/ss/lemonstandprod/1/JS-2.24/s" + Date.now() + Math.floor(Math.random() * 1e4) + "?" + qs;
  }
};
